    /// The plant of each forage, so the bloom, the move and the harvest of one forage show
    /// the same picture and read as one thread through the year.
    static let byForage: [String: YearPhoto] = [
        "rapeseed": byKey["migrate-rapeseed"]!,
        "acacia": byKey["migrate-acacia"]!,
        "chestnut": byKey["migrate-chestnut"]!,
        "linden": byKey["migrate-linden"]!,
        "fir": byKey["migrate-fir"]!,
        "lavender": byKey["migrate-lavender"]!,
        "sunflower": byKey["migrate-sunflower"]!,
        "heather": byKey["migrate-heather"]!,
    ]

    /// The photograph for one calendar entry, or nil when it has none.
    ///
    /// An entry that names a forage shows that plant, whatever the job is. Everything else
    /// shows the job itself.
    static func of(_ entryKey: String, honey: String? = nil) -> YearPhoto? {
        if let honey, let plant = byForage[honey] { return plant }
        return byKey[entryKey]
    }
